<script module lang="ts">
/**
 * A verification-code field drawn as separate digit cells (`design/components/otp-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/otp-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import { agentMember, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/otp-input.module.css'

export type OTPLength = NonNullable<OTPInputProps['length']>

export interface OTPInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: string
  disabled?: boolean
  id?: string
  /**
   * Usually set by FormField, for example for "That code didn't match".
   */
  invalid?: boolean
  /**
   * The code length, 4 or 6, which are the lengths real code systems use.
   */
  length?: 4 | 6
  /**
   * Set directly on the real input, so no hidden input is needed.
   */
  name?: string
  /**
   * Never reports a non-digit.
   */
  onChange?: (value: string) => void
  /**
   * Fires once, after `onChange`, when the code becomes full. Apps that want to verify without a
   * Verify button submit from here.
   */
  onComplete?: (code: string) => void
  /**
   * Digits only. Every write path filters and truncates to `length`.
   */
  value?: string
}

export const controlKind = 'field'
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  defaultValue,
  disabled = false,
  id: idOwn,
  invalid: invalidOwn = false,
  length = 6,
  name,
  onChange,
  onComplete,
  value,
}: OTPInputProps = $props()
const joined = joinSlot(controlKind, () => ({ disabled: disabled, name: name }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
// svelte-ignore state_referenced_locally
let uncontrolled = $state((defaultValue ?? '').replace(/\D/g, '').slice(0, length))
let focused = $state(false)
let field = $state<HTMLElement | null>(null)
const code = $derived((value ?? uncontrolled).replace(/\D/g, '').slice(0, length))
const caretIndex = $derived(code.length === length ? length - 1 : code.length)
const cells = $derived(Array.from({ length }, (_, index) => index))
const commit = $derived((next: string) =>
  ((before: string) => (
    (uncontrolled = next),
    next !== before && onChange?.(next),
    next.length === length && before.length < length && onComplete?.(next)
  ))(code),
)
const receive = $derived((event: Event) =>
  ((input: HTMLInputElement) => (
    commit(input.value.replace(/\D/g, '').slice(0, length)),
    (input.value = code)
  ))(event.target as HTMLInputElement),
)
const receivePaste = $derived(
  (event: ClipboardEvent) => (
    event.preventDefault(),
    commit((event.clipboardData?.getData('text') ?? '').replace(/\D/g, '').slice(0, length)),
    ((event.target as HTMLInputElement).value = code)
  ),
)
const pinCaret = $derived((event: Event) =>
  ((node: HTMLInputElement) =>
    (node.selectionStart !== code.length || node.selectionEnd !== code.length) &&
    node.setSelectionRange(code.length, code.length))(event.currentTarget as HTMLInputElement),
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'OTPInput',
    element: () => field,
    state: () => ({ value: code, disabled: disabled, invalid: invalid }),
    actions: {},
    secret: ['value'],
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    class={styles.root}
    data-invalid={(invalid) ? '' : undefined}
    data-disabled={(disabled) ? '' : undefined}
    data-member="otp-input"
    ><input
      bind:this={field}
      class={styles.input}
      type="text"
      value={code}
      {disabled}
      {name}
      {id}
      inputmode="numeric"
      autocomplete="one-time-code"
      spellcheck="false"
      autocapitalize="off"
      autocorrect="off"
      maxlength={length}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      aria-describedby={ariaDescribedby}
      aria-required={ariaRequired}
      aria-invalid={(invalid) ? true : undefined}
      oninput={(event) => { receive(event) }}
      onpaste={(event) => { receivePaste(event) }}
      onkeydown={(event) => { if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(event.key)) event.preventDefault() }}
      onselect={(event) => { pinCaret(event) }}
      onmouseup={(event) => { pinCaret(event) }}
      onkeyup={(event) => { pinCaret(event) }}
      onfocus={(event) => { (focused = true, pinCaret(event)) }}
      onblur={() => { focused = false }}
    />{#each cells as index (index)
      }<span
        class={styles.cell}
        aria-hidden="true"
        data-filled={(code[index] !== undefined) ? '' : undefined}
        data-caret={(focused && index === caretIndex) ? '' : undefined}
        >{#if code[index] !== undefined
          }{#each [code[index]] as digit (`${index}-${digit}`)
            }<span class={styles.digit}>{digit}</span
          >{/each
        }{/if
      }</span
    >{/each
  }</div
>{/if
}{@render joined.end?.()}
